<template><div><PageHeader title="Course detail" description="Curriculum, enrollment and performance for this course."><template #actions><RouterLink to="/app/courses" class="btn secondary">← Courses</RouterLink><RouterLink to="/app/batches/create" class="btn primary">Create batch</RouterLink></template></PageHeader><div class="card"><div class="card-pad"><div class="course-detail-head"><div><div class="chip-row"><span class="chip">{{course.code}}</span><StatusBadge :status="course.status"/></div><h2 style="font-size:28px;margin-top:10px">{{course.name}}</h2><p class="muted">{{course.category}} · {{course.duration}} hours · {{course.modules}} modules</p><p class="muted" style="max-width:700px">Build production-ready skills with a practical curriculum designed around real workflows, assessment and measurable outcomes.</p></div><div class="course-icon" style="width:54px;height:54px;font-size:20px">{{course.code.slice(0,1)}}</div></div></div><div class="metric-strip"><div><span>Learners</span><strong>{{course.learners}}</strong></div><div><span>Completion</span><strong>{{course.completion}}%</strong></div><div><span>Active batches</span><strong>4</strong></div><div><span>Avg. score</span><strong>86%</strong></div></div><div class="tabs"><button class="active">Overview</button><button>Curriculum</button><button>Batches</button><button>Learners</button><button>Materials</button><button>Assessments</button><button>Analytics</button></div><div class="card-pad"><div class="grid-2" style="margin-top:0"><div><h3 style="font-size:15px">Curriculum</h3><div class="notice-list" style="margin-top:14px"><div v-for="(m,i) in modules" :key="i" class="notice-item"><span class="course-icon" style="width:30px;height:30px">{{String(i+1).padStart(2,'0')}}</span><div class="notice-copy"><strong>{{m}}</strong><p>Learning module · practical exercises · assessment checkpoints</p></div><span class="chip">~3h</span></div></div></div><div><h3 style="font-size:15px">Learning outcomes</h3><div class="notice-list" style="margin-top:14px"><div v-for="item in outcomes" :key="item" class="notice-item"><span style="color:#15803d;font-weight:800">✓</span><div class="notice-copy"><strong>{{item}}</strong><p>Mapped to course objectives and completion criteria.</p></div></div></div></div></div></div></div></div></template>
<script setup lang="ts">import {computed} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '../components/PageHeader.vue';import StatusBadge from '../components/StatusBadge.vue';import {courses} from '../data/mock';const route=useRoute();const course=computed(()=>courses.find(c=>c.id===Number(route.params.id))||courses[0]);const modules=['Introduction','Laravel Architecture','Routing','Database','Authentication','REST APIs','Testing','Deployment'];const outcomes=['Build a Laravel application from scratch','Design and secure REST APIs','Implement authentication and role-based access','Work confidently with relational data'];</script>
